#include<iostream>
#include<cstring>
using namespace std;
bool used[10]={false};
int first,second;
void dfs(int k, int num)
{
    if(k==3)
    {
        first=num;
        num=0;
    }
    else if(k==6)
    {
        second = num;
        num=0;
    }
    else if (k == 9)
    {
        if(num%3==0 and num/3==first and first*2==second)
            cout<<first<<' '<<second<<' '<<num<<endl;
        return;
    }
    for(int i=1;i<=9;i++)
    {
        if(not used[i])
        {
            used[i]=true;
            dfs(k+1, num*10+i);
            used[i]=false;
        }
    }
}
int main()
{
    memset(used, 0, sizeof(used));
    for(int i=1;i<=9;i++)
    {
        used[i]=true;
        dfs(1, i);
        used[i]=false;
    }
    return 0;
}
